                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
        }
        return closeAndRecord(sheetId, user, period, "");
    }

    /** Close, in order of their to-dates, every open period of the sheet whose to-date plus its grace days is
     *  before its today, each exactly as a close by hand. Called with the sheet locked, once its new today is set. */
    @Transactional
    public void closePastGrace(Sheet sheet, String user) {
        if (sheet.getGraceDays() == null) {
            return;
        }
        periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
                .filter(p -> !p.isClosed() && sheet.pastGrace(p.getToDate()))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> closeAndRecord(sheet.getId(), user, p, " auto=yes"));
    }

    /** Fix a period's due-total as it is now and record the close; the audit line ends with the suffix given. */
    private Period closeAndRecord(String sheetId, String user, Period period, String suffix) {
        period.close(rollup.dueByPersonBetween(sheetId, period.getFromDate(), period.getToDate()));
        Period closed = periods.saveAndFlush(period);
        BigDecimal total = closed.getClosedTotal();
        audit.recordChangeOnCommit(sheetId, user, "PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + closed.getName()
                + " total=" + total.toPlainString() + suffix);
        return closed;
    }

    /** Reopen a closed period, making its due-total live again; only a role the permission matrix allows may (by
     *  default a steward), and it is refused when the period is open. */
    @Transactional
    public Period reopen(String sheetId, String user, String name) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        if (!sheet.allows("reopen", roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (!period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
        }
        period.reopen();
        Period reopened = periods.saveAndFlush(period);
        audit.recordChangeOnCommit(sheetId, user, "PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + reopened.getName());
        return reopened;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
    }
}
-- Periods on a sheet: a name unique on the sheet and an inclusive from and to date. No two periods
-- of a sheet overlap (checked when one is added, with the sheet locked); a claim belongs to the
-- period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CONSTRAINT period_from_to CHECK (from_date <= to_date),
    CONSTRAINT period_sheet_name UNIQUE (sheet_id, name)
);
-- A closed period: its due-total is fixed at the moment it was closed (closed_total), so later rate
-- changes leave it as it is, and no claim dated inside it can be added, edited or moved.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
-- Each person's due-total for a closed period, fixed at the moment it was closed; the period's closed_total is
-- their sum. A person with no line (added later) has 0.00 for it. Removed when the period is reopened.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    due_total DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- The sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim opened
-- is numbered within the period its date is in (<period name>-<n>), or X-<n> when in none. None means off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;

-- A claim's number (and the number a correction names) is now text: a sheet-wide number (1, 2, ...) or a
-- number within a period (P1-1, X-1).
ALTER TABLE claim DROP CONSTRAINT claim_number_unique;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(120);
ALTER TABLE claim ADD CONSTRAINT claim_number_unique UNIQUE (sheet_id, claim_number);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);

-- The last number given in each period sequence of a sheet, keyed by the number's prefix (the period's name,
-- or X for claims in no period). Numbers are never given again.
CREATE TABLE claim_sequence (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet (id),
    prefix      VARCHAR(100) NOT NULL,
    last_number INT          NOT NULL,
    CONSTRAINT claim_sequence_sheet_prefix UNIQUE (sheet_id, prefix)
);

